package com.vettid.core.chain

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * W1 conformance: the app-side PSBT code against vettid-vault's own answers (`Vectors`, generated by running the vault's
 * `btc.Inspect`, `btc.BuildPSBT`, `summaryJSON`, `psbtError` and `parsePSBT` at vettid-vault origin/main 214b88f; nothing is written by
 * hand). Three claims, each over every vector:
 *  1. [PsbtInspector] gives the vault's answer: the same refusal reason, or the same summary BYTE FOR BYTE in the vault's serialization.
 *  2. [PsbtBuilder] given the vector's coins and payees makes the same PSBT BYTE FOR BYTE as the vault's `BuildPSBT`, and refuses
 *     what the vault refuses, with the vault's reason.
 *  3. [PsbtBase64] reads the `psbt` member as the vault does (bad_request for text it will not decode).
 * A failure lists every case that differs, not the first.
 */
class VaultConformanceTest {
    private val cases = Vectors.cases

    private fun decode(c: Vectors.Case): ByteArray? = PsbtBase64.decode(c.psbt)

    @Test
    fun vectors_are_there_and_cover_the_vaults_reasons() {
        assertTrue("${cases.size} vectors", cases.size >= 130)
        val reasons = cases.mapNotNull { it.reason }.toSet()
        // Every invalid_psbt reason of VAULT-MESSAGING §10.18 that a PSBT alone can cause (not no_account / wrong_seed / the
        // payment-request ones, which are not about the PSBT).
        val wanted = setOf(
            "size", "malformed", "shape", "version", "duplicate_input", "previous_tx", "witness_utxo", "sighash", "input_script", "amount",
            "foreign_input", "derivation_path", "derivation_key", "derivation_script", "internal_key", "output_amount", "output_script",
                "fee", "fee_rate",
        )
        assertEquals("reasons without a vector", emptySet<String>(), wanted - reasons)
        assertEquals(setOf("regtest", "mainnet", "testnet", "testnet4", "signet"), Vectors.wallets.keys)
        // both accounts in one PSBT, taproot with non_witness_utxo, on four networks
        assertTrue(cases.any { it.name == "mainnet/ok_mixed_payee_kinds" && it.ok })
        assertTrue(cases.any { it.name == "regtest/ok_mixed_accounts_change_p2tr" && it.ok })
    }

    @Suppress("LoopWithTooManyJumpStatements")
    @Test
    fun inspector_gives_the_vaults_answer_for_every_vector() {
        val failures = ArrayList<String>()
        var ok = 0
        var refused = 0
        var members = 0
        var differences = 0
        for (c in cases) {
            val wallet = Vectors.wallets.getValue(c.wallet)
            val raw = decode(c)
            if (raw == null) {
                members++
                if (c.code != "bad_request") failures += "${c.name}: app cannot decode the member, vault says ${c.expect}"
                continue
            }
            if (c.code != null) {
                failures += "${c.name}: vault says ${c.code} but the app decoded it"
                continue
            }
            val result = PsbtInspector.inspect(wallet, raw)
            c.appDifference?.let { (app, why) ->
                // An expected difference: the app must give exactly the declared answer, and the vault's must be the other one.
                val got = if (result is InspectResult.Ok) "ok" else (result as InspectResult.Refused).reason
                if (why.isBlank() || got != app) failures += "${c.name}: app says $got, declared difference is $app ($why)"
                differences++
                continue
            }
            val r = result
            when (r) {
                is InspectResult.Ok -> {
                    if (!c.ok) failures += "${c.name}: app accepts, vault refuses with ${c.reason}"
                    else if (r.summary.toJson() != c.summaryJson) failures +=
                        "${c.name}: summary differs\n  app:   ${r.summary.toJson()}\n  vault: ${c.summaryJson}"
                    else ok++
                }
                is InspectResult.Refused -> {
                    if (c.ok) failures += "${c.name}: app refuses with ${r.reason}, vault accepts"
                    else if (r.reason != c.reason) failures += "${c.name}: app says ${r.reason}, vault says ${c.reason}"
                    else refused++
                }
            }
        }
        println(
            "W1 inspect conformance: $ok summaries identical, $refused refusals identical, " +
                "$members undecodable members identical, $differences declared differences, " +
                "${failures.size} unexpected differences, ${cases.size} vectors",
        )
        assertEquals("expected differences with the vault (Bip174.kt documents each; vault erratum)", 5, differences)
        if (failures.isNotEmpty()) fail(failures.joinToString("\n"))
    }

    @Test
    fun the_vaults_summary_reads_and_writes_back_unchanged() {
        var n = 0
        for (c in cases.filter { it.ok }) {
            assertEquals(c.name, c.summaryJson, InspectSummary.fromJson(c.summaryJson).toJson())
            n++
        }
        assertTrue(n >= 30)
    }

    @Test
    fun builder_makes_the_vaults_bytes_and_refuses_with_the_vaults_reasons() {
        val failures = ArrayList<String>()
        var same = 0
        var refused = 0
        var withBuild = 0
        for (c in cases) {
            val b = c.build ?: continue
            withBuild++
            val wallet = Vectors.wallets.getValue(c.wallet)
            val want = decode(c)
            try {
                val got = PsbtBuilder.build(wallet, Vectors.coins(b), Vectors.outputs(b))
                if (want == null || !c.ok) failures += "${c.name}: builder made a PSBT; vault says ${c.reason ?: c.code}"
                else if (!got.contentEquals(want)) failures +=
                    "${c.name}: bytes differ at ${firstDiff(got, want)} (app ${got.size} bytes, vault ${want.size})"
                else same++
            } catch (e: BuildException) {
                if (c.ok) failures += "${c.name}: builder refuses with ${e.reason}, vault accepts"
                else if (e.reason != c.reason) failures += "${c.name}: builder says ${e.reason}, vault says ${c.reason}"
                else refused++
            }
        }
        println(
            "W1 builder conformance: $same PSBTs byte-identical, $refused refusals identical, ${failures.size} differences, " +
                "$withBuild vectors with a build recipe",
        )
        if (failures.isNotEmpty()) fail(failures.joinToString("\n"))
    }

    @Test
    fun a_psbt_member_is_read_as_the_vault_reads_it() {
        val raw = decode(cases.first { it.name == "regtest/ok_p2wpkh_two_inputs_change" })!!
        assertEquals(raw.toList(), PsbtBase64.decode(PsbtBase64.encode(raw))!!.toList())
        assertNull(PsbtBase64.decode(""))
        assertEquals(listOf<Byte>(0, 0), PsbtBase64.decode("AAA=")!!.toList())
        assertNull(PsbtBase64.decode("AAB=")) // non-zero padding bits: Go's StdEncoding.Strict() refuses it
        assertNull(PsbtBase64.decode("A".repeat(PsbtBase64.MAX_CHARS + 4)))
    }

    private fun firstDiff(a: ByteArray, b: ByteArray): Int {
        for (i in 0 until minOf(a.size, b.size)) if (a[i] != b[i]) return i
        return minOf(a.size, b.size)
    }
}
